<?php if (!$tasks): ?><p class="muted">No unfinished tasks. Make space for what matters next.</p><?php else: foreach ($tasks as $t): ?><div class="task-row"><div><strong><?= e($t['title']) ?></strong><small class="<?= $t['due'] && $t['due']<date('Y-m-d') ? 'error-text' : '' ?>"><?= e(ucfirst($t['source'] ?? 'manual')) ?><?= $t['due'] ? ' · '.e($t['due']) : ' · No due date' ?><?= $t['due'] && $t['due']<date('Y-m-d') ? ' · Overdue' : '' ?></small></div><form method="post" action="/tasks/<?= e($t['id']) ?>/done"><?= csrf_field() ?><input type="hidden" name="return_to" value="<?= e($returnTo ?? '/lessons') ?>"><button class="secondary">Done</button></form></div><?php endforeach; endif; ?>
